const readTool = {
  name: 'read_file',
  description: 'Read one text file from the course folder.',
  params: {
    path: { type: 'string', required: true },
    limit: { type: 'number', required: false }
  }
};
console.log(readTool.params.path.type);

function validateToolCall(call, schema) {
  if (call.name !== schema.name) {
    return { ok: false, error: 'unknown tool: ' + call.name };
  }
  const args = call.args || {};
  for (const key of Object.keys(args)) {
    if (!schema.params[key]) {
      return { ok: false, error: 'unknown parameter: ' + key };
    }
  }
  for (const key of Object.keys(schema.params)) {
    const rule = schema.params[key];
    const value = args[key];
    if (rule.required && value === undefined) {
      return { ok: false, error: 'missing required parameter: ' + key };
    }
    if (value !== undefined && typeof value !== rule.type) {
      return { ok: false, error: key + ' must be a ' + rule.type };
    }
  }
  return { ok: true, value: args };
}

const schema = {
  name: 'read_file',
  params: {
    path: { type: 'string', required: true },
    limit: { type: 'number', required: false }
  }
};
const calls = [
  { name: 'read_file', args: { path: 'notes.txt' } },
  { name: 'read_file', args: { path: 42 } },
  { name: 'read_file', args: { path: 'a.txt', extra: true } }
];
for (const call of calls) {
  const result = validateToolCall(call, schema);
  console.log(result.ok ? 'OK ' + JSON.stringify(result.value) : 'REJECT ' + result.error);
}

