// Educational mini agent. The scripted policy STANDS IN for a language model:
// no AI provider is used, no real files are written, output is deterministic.
const APPROVAL = true; // simulated human approval for the one write action

const files = {
  'notes/plan.txt': 'plan: fix the failing test in src/math.test.js',
  'src/math.js': 'function add(a, b) { return a - b; }',
  'src/math.test.js': 'test: add(2, 2) must return 4'
};

const readSchema = {
  name: 'read_file',
  params: { path: { type: 'string', required: true } }
};

function validateCall(call, schema) {
  if (call.name !== schema.name) return { ok: false, error: 'unknown tool' };
  const args = call.args || {};
  for (const key of Object.keys(args)) {
    if (!schema.params[key]) return { ok: false, error: 'unknown parameter ' + key };
  }
  for (const key of Object.keys(schema.params)) {
    const rule = schema.params[key];
    if (rule.required && args[key] === undefined) return { ok: false, error: 'missing ' + key };
    if (args[key] !== undefined && typeof args[key] !== rule.type) return { ok: false, error: key + ' must be ' + rule.type };
  }
  return { ok: true, value: args };
}

function toolReadFile(args) {
  if (!(args.path in files)) return { ok: false, error: 'file not found' };
  return { ok: true, value: files[args.path] };
}

function toolWriteFile(args) {
  if (!APPROVAL) return { ok: false, error: 'write blocked: no human approval' };
  files[args.path] = args.content; // mock write: memory only, the real disk is untouched
  return { ok: true, value: 'written ' + args.content.length + ' chars' };
}

// Scripted policy: it plays the role of the model step by step.
const plan = [
  { reason: 'read the plan first', tool: 'read_file', args: { path: 'notes/plan.txt' } },
  { reason: 'read the code under test', tool: 'read_file', args: { path: 'src/math.js' } },
  { reason: 'read the test', tool: 'read_file', args: { path: 'src/math.test.js' } },
  { reason: 'save the fix report', tool: 'write_file', args: { path: 'notes/report.txt', content: 'found: add() subtracts; fix: return a + b' } }
];

const task = 'Find the bug described in notes/plan.txt and report it';
const log = [];
const context = [];
console.log('TASK: ' + task);
let report = 'no report';
const maxSteps = 6;
for (let i = 0; i < plan.length && i < maxSteps; i = i + 1) {
  const step = plan[i];
  const call = { name: step.tool, args: step.args };
  const check = step.tool === 'read_file'
    ? validateCall(call, readSchema)
    : { ok: true, value: step.args };
  if (!check.ok) {
    log.push('step ' + (i + 1) + ' invalid call: ' + check.error);
    break;
  }
  const result = step.tool === 'read_file'
    ? toolReadFile(check.value)
    : toolWriteFile(check.value);
  if (!result.ok) {
    log.push('step ' + (i + 1) + ' ' + step.tool + ': ' + result.error);
    break;
  }
  context.push(step.tool + ' ' + step.args.path + ' -> ' + result.value.slice(0, 30));
  if (step.tool === 'write_file') report = step.args.content;
}
console.log('CONTEXT:');
for (const line of context) console.log('- ' + line);
console.log('ERRORS: ' + (log.length === 0 ? 'none' : log.join('; ')));
console.log('REPORT: ' + report);
